import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int x_input = Integer.parseInt(inputLine[0]);
        int y_input = Integer.parseInt(inputLine[1]);

        List<Integer> primes = generatePrimes(6000);
        Map<Integer, Integer> primeFactorsCache = new HashMap<>();
        Map<Integer, List<Integer>> factorsCache = new HashMap<>();
        Map<Integer, Integer> fCache = new HashMap<>();
        fCache.put(0, 0);
        fCache.put(1, 1);
        fCache.put(2, 2);
        int m = y_input;

        int result = calculateF(x_input, m, primes, primeFactorsCache, factorsCache, fCache);
        System.out.println(result);
    }

    private static List<Integer> generatePrimes(int limit) {
        List<Integer> primes = new ArrayList<>();
        for (int candidate = 2; candidate < limit; candidate++) {
            boolean isPrime = true;
            for (int prime : primes) {
                if (prime * prime > candidate) {
                    break;
                }
                if (candidate % prime == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(candidate);
            }
        }
        return primes;
    }

    private static Map<Integer, Integer> factorization(int n, List<Integer> primes, Map<Integer, Integer> cache) {
        if (cache.containsKey(n)) {
            Map<Integer, Integer> result = new HashMap<>();
            result.putAll(cache.get(n));
            return result;
        }
        Map<Integer, Integer> factors = new HashMap<>();
        int tempN = n;
        for (int prime : primes) {
            if (prime * prime > tempN) {
                break;
            }
            int count = 0;
            while (tempN % prime == 0) {
                tempN /= prime;
                count++;
            }
            if (count > 0) {
                factors.put(prime, count);
            }
        }
        if (tempN > 1) {
            factors.put(tempN, 1);
        }
        cache.put(n, new HashMap<>(factors));
        return factors;
    }

    private static List<Integer> generateAllFactors(int n, List<Integer> primes, Map<Integer, Integer> primeFactorsCache, Map<Integer, List<Integer>> factorsCache) {
        if (factorsCache.containsKey(n)) {
            return factorsCache.get(n);
        }
        Map<Integer, Integer> primeFactors = factorization(n, primes, primeFactorsCache);
        List<Integer> resultFactors = new ArrayList<>();
        resultFactors.add(1);
        for (Map.Entry<Integer, Integer> entry : primeFactors.entrySet()) {
            int prime = entry.getKey();
            int count = entry.getValue();
            List<Integer> newFactors = new ArrayList<>();
            for (int val : resultFactors) {
                for (int exp = 0; exp <= count; exp++) {
                    newFactors.add(val * (int)Math.pow(prime, exp));
                }
            }
            resultFactors = newFactors;
        }
        factorsCache.put(n, resultFactors);
        return resultFactors;
    }

    private static int calculateF(int n, int m, List<Integer> primes, Map<Integer, Integer> primeFactorsCache, Map<Integer, List<Integer>> factorsCache, Map<Integer, Integer> fCache) {
        for (int i = 3; i <= n; i++) {
            int f_i = 2 * fCache.get(i - 1);
            List<Integer> divisors = generateAllFactors(i, primes, primeFactorsCache, factorsCache);
            for (int divisor : divisors) {
                if (divisor >= 2 && divisor <= i) {
                    int term = fCache.get(i / divisor) - fCache.get((i - 1) / divisor);
                    f_i += term;
                }
            }
            f_i %= m;
            fCache.put(i, f_i);
        }
        return fCache.get(n);
    }
}
